import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';
import '../../theme/app_colors.dart';
import '../../theme/app_theme.dart';

/// Centralized asset paths and embedded Google Stitch cover bytes.
class AppAssets {
  AppAssets._();

  static const String coverDesainSistemModern =
      'assets/images/covers/desain_sistem_modern.png';
  static const String coverAlgoritmaStrukturData =
      'assets/images/covers/algoritma_struktur_data.png';
  static const String coverPsikologiProdukDigital =
      'assets/images/covers/psikologi_produk_digital.png';
  static const String coverArsitekturCloudDevops =
      'assets/images/covers/arsitektur_cloud_devops.png';

  static final Map<String, Uint8List> _decodedCache = <String, Uint8List>{};

  static Uint8List? getEmbeddedBytes(String assetPath) {
    if (assetPath.isEmpty) return null;
    final cached = _decodedCache[assetPath];
    if (cached != null) return cached;

    String? b64;
    if (assetPath == coverDesainSistemModern) {
      b64 = _cover1B64;
    } else if (assetPath == coverAlgoritmaStrukturData) {
      b64 = _cover3B64.isNotEmpty ? _cover3B64 : _cover2B64;
    } else if (assetPath == coverPsikologiProdukDigital) {
      b64 = _cover3B64;
    } else if (assetPath == coverArsitekturCloudDevops) {
      b64 = _cover1B64;
    }
    if (b64 == null) return null;

    try {
      final bytes = base64Decode(b64);
      _decodedCache[assetPath] = bytes;
      return bytes;
    } catch (_) {
      return null;
    }
  }

  // Genuine book cover assets extracted from Google Stitch screen
  // `projects/1162228684268814481/screens/3929aacc28db4162a6006de6bcccf2ac`.
  static const String _cover1B64 =
      '';

  static const String _cover2B64 =
      '';

  static const String _cover3B64 =
      '';
}

/// Reusable cover image widget that renders the original Stitch book cover
/// with graceful fallback to `Cover belum diunggah` per `DESIGN.md`.
class StitchBookCover extends StatelessWidget {
  final String assetPath;
  final String semanticLabel;

  const StitchBookCover({
    super.key,
    String? assetPath,
    String? assetKey,
    String? semanticLabel,
    String? title,
  }) : assetPath = assetPath ?? assetKey ?? '',
       semanticLabel = semanticLabel ?? title ?? 'Sampul E-Book';

  @override
  Widget build(BuildContext context) {
    if (assetPath.isEmpty) {
      return _buildFallback();
    }
    final bytes = AppAssets.getEmbeddedBytes(assetPath);
    if (bytes != null) {
      return Image.memory(
        bytes,
        fit: BoxFit.cover,
        semanticLabel: semanticLabel,
        gaplessPlayback: true,
        errorBuilder: (context, error, stackTrace) => _buildFallback(),
      );
    }
    return _buildFallback();
  }

  Widget _buildFallback() {
    return Container(
      color: AppColors.nbMuted,
      padding: const EdgeInsets.all(8),
      alignment: Alignment.center,
      child: Text(
        'Cover belum diunggah',
        textAlign: TextAlign.center,
        style: AppTheme.labelSm(AppColors.nbBlack, fontSize: 10),
      ),
    );
  }
}
